summary:
bash: cd /opt/src/klee && python3 - <<'EOF'
import re
p = 'lib/Solver/STPSolver.cpp'
s = open(p).read()
old1 = """  case SAT::RISS: {
    SATSolverAvailable = vc_useRiss(vc);
    break;
  }"""
new1 = """  case SAT::RISS: {
    // STP >= 2.4 removed the Riss SAT backend; fall back to minisat.
    klee_warning("RISS is no longer supported by STP; using minisat instead");
    SATSolverAvailable = vc_useMinisat(vc);
    break;
  }"""
old2 = """  else if (vc_isUsingCryptominisat(vc))
    SATName = SATNames[SAT::CRYPTOMINISAT];
  else if (vc_isUsingRiss(vc))
    SATName = SATNames[SAT::RISS];"""
new2 = """  else if (vc_isUsingCryptominisat(vc))
    SATName = SATNames[SAT::CRYPTOMINISAT];"""
assert s.count(old1) == 1 and s.count(old2) == 1, (s.count(old1), s.count(old2))
s = s.replace(old1, new1).replace(old2, new2)
open(p, 'w').write(s)
print("patched")
EOF

